def grade_review(card_id: str, grade: Grade, reviewed_at: dt, seconds: int, settings: SchedulerSettings) -> Generator[object, object, Card]:
    repo = yield from need(CardRepository)
    card = repo.get_card(card_id)
    if card is None:
        return (yield from throw(CardNotFound(card_id)))
    graded = grade_card(card, grade, reviewed_at, seconds, settings)
    repo.save_card(graded)
    all_cards = repo.list_cards()
    updated_cards = bury_siblings(all_cards, card_id, reviewed_at.date())
    for updated_card in updated_cards:
        if updated_card.id != card_id:
            original_card = next((c for c in all_cards if c.id == updated_card.id), None)
            if updated_card != original_card:
                repo.save_card(updated_card)
    return graded

